import { useId, useRef, useState, type ComponentProps } from "react";
import { Button } from "./button";
import { Combobox } from "./combobox";
import { NativeSelect } from "./native-select";
import { Switch } from "./switch";
import { cn } from "./utils";

type SharePrincipalKind = "person" | "group" | "link";

type SharePrincipal = {
    id: string;
    kind: SharePrincipalKind;
    name: string;
    description?: string;
    disabled?: boolean;
};

type PermissionRole = {
    id: string;
    label?: string;
    state: "known" | "unknown";
};

type PermissionGrant = {
    id: string;
    principal: SharePrincipal;
    role: PermissionRole;
};

type PermissionResolution =
    | { state: "known"; role: PermissionRole }
    | { state: "pending"; message?: string }
    | { state: "unknown"; message?: string }
    | { state: "inaccessible"; message?: string };

type EffectivePermission = {
    principal: SharePrincipal;
    result: PermissionResolution;
};

type ShareLinkAccess =
    | { state: "known"; enabled: boolean; role: PermissionRole }
    | { state: "pending"; message?: string }
    | { state: "unknown"; message?: string }
    | { state: "inaccessible"; message?: string };

type SharePermissionPanelProps = Omit<
    ComponentProps<"section">,
    "children" | "aria-label"
> & {
    accessState: "available" | "pending" | "unknown" | "inaccessible";
    canManage: boolean;
    directGrants: readonly PermissionGrant[];
    inheritedGrants: readonly PermissionGrant[];
    effectivePermissions: readonly EffectivePermission[];
    linkAccess: ShareLinkAccess;
    roles: readonly PermissionRole[];
    principalOptions?: readonly SharePrincipal[];
    defaultGrantRoleId?: string;
    onPrincipalQueryChange?: (query: string) => void;
    loadingPrincipals?: boolean;
    principalError?: string | null;
    onAddGrant?: (
        principal: SharePrincipal,
        roleId: string,
    ) => void | Promise<void>;
    onRoleChange?: (
        grantId: string,
        roleId: string,
    ) => void | Promise<void>;
    onRemoveGrant?: (grantId: string) => void | Promise<void>;
    onLinkAccessChange?: (change: {
        enabled: boolean;
        roleId: string;
    }) => void | Promise<void>;
    label?: string;
    saveError?: string | null;
    saveErrorMessage?: string;
};

function validatePrincipal(principal: SharePrincipal) {
    if (!principal.id.trim() || !principal.name.trim()) {
        throw new Error(
            "SharePermissionPanel principals need IDs and names.",
        );
    }
}

function principalKey(principal: Pick<SharePrincipal, "id" | "kind">) {
    return JSON.stringify([principal.kind, principal.id]);
}

function displayRole(
    role: PermissionRole,
    roles: readonly PermissionRole[],
) {
    const knownRole = role.state === "known"
        ? roles.find((option) =>
            option.id === role.id && option.state === "known",
        )
        : undefined;
    if (!knownRole) return `알 수 없는 역할 (${role.label || role.id})`;
    return knownRole.label ?? knownRole.id;
}

function roleSelectOptions(
    role: PermissionRole,
    roles: readonly PermissionRole[],
) {
    const knownRoles = roles.filter((option) => option.state === "known");
    const currentIsKnown = role.state === "known" &&
        knownRoles.some((option) => option.id === role.id);
    const selectableRoles = currentIsKnown
        ? knownRoles
        : knownRoles.filter((option) => option.id !== role.id);
    return [
        ...(!currentIsKnown ? [{
            ...role,
            state: "unknown" as const,
            label: displayRole(role, roles),
        }] : []),
        ...selectableRoles,
    ];
}

function permissionStateLabel(result: PermissionResolution) {
    switch (result.state) {
        case "known":
            return null;
        case "pending":
            return result.message ?? "실효 권한을 확인하는 중입니다.";
        case "unknown":
            return result.message ?? "실효 권한을 확인할 수 없습니다.";
        case "inaccessible":
            return result.message ?? "실효 권한에 접근할 수 없습니다.";
    }
}

function SharePermissionPanel({
    accessState,
    canManage,
    directGrants,
    inheritedGrants,
    effectivePermissions,
    linkAccess,
    roles,
    principalOptions = [],
    defaultGrantRoleId,
    onPrincipalQueryChange,
    loadingPrincipals = false,
    principalError = null,
    onAddGrant,
    onRoleChange,
    onRemoveGrant,
    onLinkAccessChange,
    label = "공유 및 권한",
    saveError = null,
    saveErrorMessage = "권한을 저장하지 못했습니다. 다시 시도하세요.",
    className,
    ...props
}: SharePermissionPanelProps) {
    const generatedId = useId();
    const pendingRef = useRef(false);
    const knownRoles = roles.filter((role) => role.state === "known");
    const [pendingAction, setPendingAction] = useState<string | null>(null);
    const [actionError, setActionError] = useState<string | null>(null);
    const [selectedPrincipal, setSelectedPrincipal] =
        useState<SharePrincipal | null>(null);
    const [grantRoleId, setGrantRoleId] = useState(
        defaultGrantRoleId ?? knownRoles[0]?.id ?? "",
    );
    const eligiblePrincipals = principalOptions.filter((principal) =>
        principal.kind !== "link",
    );
    const principalMap = new Map(eligiblePrincipals.map((principal) => [
        principalKey(principal),
        principal,
    ]));
    const mayEdit = accessState === "available" && canManage;
    const busy = pendingAction !== null || loadingPrincipals;
    const selectedGrantRoleId = knownRoles.some((role) =>
        role.id === grantRoleId,
    ) ? grantRoleId : knownRoles[0]?.id ?? "";

    if (!label.trim()) {
        throw new Error("SharePermissionPanel requires a label.");
    }
    const roleIds = new Set<string>();
    for (const role of roles) {
        if (!role.id.trim() || (role.state === "known" &&
            !role.label?.trim())) {
            throw new Error(
                "SharePermissionPanel roles need IDs and labels.",
            );
        }
        if (roleIds.has(role.id)) {
            throw new Error(
                `SharePermissionPanel role ID is duplicated: ${role.id}`,
            );
        }
        roleIds.add(role.id);
    }
    for (const principal of principalOptions) validatePrincipal(principal);
    const principalKeys = new Set(
        principalOptions.map((item) => principalKey(item)),
    );
    if (principalKeys.size !== principalOptions.length) {
        throw new Error(
            "SharePermissionPanel principal kind and ID pairs must be unique.",
        );
    }
    const grantIds = new Set<string>();
    for (const grant of [...directGrants, ...inheritedGrants]) {
        if (!grant.id.trim()) {
            throw new Error("SharePermissionPanel grant IDs must be named.");
        }
        if (grantIds.has(grant.id)) {
            throw new Error(
                `SharePermissionPanel grant ID is duplicated: ${grant.id}`,
            );
        }
        grantIds.add(grant.id);
        validatePrincipal(grant.principal);
    }
    for (const permission of effectivePermissions) {
        validatePrincipal(permission.principal);
    }

    async function runAction(
        actionId: string,
        action: () => void | Promise<void>,
    ) {
        if (!mayEdit || pendingRef.current) return;
        pendingRef.current = true;
        setPendingAction(actionId);
        setActionError(null);
        try {
            await action();
        } catch {
            setActionError(saveErrorMessage);
        } finally {
            pendingRef.current = false;
            setPendingAction(null);
        }
    }

    function renderGrant(
        grant: PermissionGrant,
        source: "direct" | "inherited",
    ) {
        const editable = source === "direct" && mayEdit;
        const options = roleSelectOptions(grant.role, roles);
        const selectedRole = options.find((option) =>
            option.id === grant.role.id,
        );
        return (
            <li key={grant.id}
                className={
                    "grid min-w-0 gap-2 rounded-sm border border-border " +
                    "bg-surface p-[var(--space-3)] @md:grid-cols-[minmax(0,1fr)_auto] " +
                    "@md:items-center"
                }>
                <div className="min-w-0">
                    <p className="m-0 break-words text-sm font-medium">
                        {grant.principal.name}
                    </p>
                    <p className="m-0 text-xs text-muted">
                        {grant.principal.kind}
                        {grant.principal.description
                            ? ` · ${grant.principal.description}` : ""}
                    </p>
                </div>
                {editable ? (
                    <div className="flex min-w-0 items-center gap-2">
                        <NativeSelect
                            aria-label={`${grant.principal.name} 역할`}
                            value={grant.role.id}
                            disabled={busy || !onRoleChange}
                            onChange={(event) => {
                                const nextRoleId = event.target.value;
                                if (nextRoleId && onRoleChange) {
                                    void runAction(`role:${grant.id}`, () =>
                                        onRoleChange(grant.id, nextRoleId),
                                    );
                                }
                            }}>
                            {selectedRole?.state === "unknown" && (
                                <option value={selectedRole.id} disabled>
                                    {selectedRole.label ?? selectedRole.id}
                                </option>
                            )}
                            {options.filter((role) => role.state === "known")
                                .map((role) => (
                                <option key={role.id} value={role.id}>
                                    {role.label ?? role.id}
                                </option>
                                ))}
                        </NativeSelect>
                        <Button type="button" variant="outline"
                            disabled={busy || !onRemoveGrant}
                            aria-label={`${grant.principal.name} 공유 제거`}
                            onClick={() => {
                                if (onRemoveGrant) {
                                    void runAction(`remove:${grant.id}`, () =>
                                        onRemoveGrant(grant.id),
                                    );
                                }
                            }}>
                            제거
                        </Button>
                    </div>
                ) : (
                    <p className="m-0 text-sm text-foreground">
                        {displayRole(grant.role, roles)}
                    </p>
                )}
            </li>
        );
    }

    return (
        <section {...props} aria-label={label}
            aria-busy={busy || undefined}
            className={cn("@container grid min-w-0 gap-5", className)}>
            <h2 className="m-0 text-base font-semibold text-foreground">
                {label}
            </h2>
            {accessState !== "available" && (
                <p role={accessState === "inaccessible" ? "alert" : "status"}
                    className={cn(
                        "m-0 rounded-sm border border-border bg-surface-subtle " +
                        "p-[var(--space-3)] text-sm",
                        accessState === "inaccessible" && "text-danger",
                        accessState !== "inaccessible" && "text-muted",
                    )}>
                    {accessState === "pending" &&
                        "공유 권한을 불러오는 중입니다."}
                    {accessState === "unknown" &&
                        "공유 권한을 확인할 수 없습니다."}
                    {accessState === "inaccessible" &&
                        "공유 권한에 접근할 수 없습니다."}
                </p>
            )}
            {accessState === "available" && !canManage && (
                <p role="status" className="m-0 text-sm text-muted">
                    공유 권한을 확인할 수 있지만 변경할 수는 없습니다.
                </p>
            )}
            {saveError && (
                <p role="alert" className="m-0 text-sm text-danger">
                    {saveError}
                </p>
            )}
            {actionError && (
                <p role="alert" className="m-0 text-sm text-danger">
                    {actionError}
                </p>
            )}

            <section aria-labelledby={`${generatedId}-direct-heading`}
                className="grid min-w-0 gap-3">
                <h3 id={`${generatedId}-direct-heading`}
                    className="m-0 text-sm font-semibold">
                    직접 부여
                </h3>
                {accessState === "available" && directGrants.length > 0 ? (
                    <ul className="m-0 grid list-none gap-2 p-0">
                        {directGrants.map((grant) =>
                            renderGrant(grant, "direct"),
                        )}
                    </ul>
                ) : accessState === "available" ? (
                    <p className="m-0 text-sm text-muted">
                        직접 부여된 권한이 없습니다.
                    </p>
                ) : (
                    <p className="m-0 text-sm text-muted">
                        직접 부여 결과를 확인할 수 없습니다.
                    </p>
                )}
                {mayEdit && onAddGrant && (
                    <div className={
                        "grid min-w-0 gap-2 rounded-sm border " +
                        "border-border p-[var(--space-3)] " +
                        "@md:grid-cols-[minmax(0,1fr)_minmax(8rem,0.7fr)_auto]"
                    }>
                        <Combobox
                            aria-label="공유할 사용자 또는 그룹"
                            placeholder="사용자 또는 그룹 검색"
                            options={eligiblePrincipals.map((principal) => ({
                                value: principalKey(principal),
                                label: `${principal.name} (${principal.kind})`,
                                disabled: principal.disabled,
                            }))}
                            value={selectedPrincipal
                                ? principalKey(selectedPrincipal) : null}
                            filterOptions={!onPrincipalQueryChange}
                            selectedOption={selectedPrincipal ? {
                                value: principalKey(selectedPrincipal),
                                label: `${selectedPrincipal.name} ` +
                                    `(${selectedPrincipal.kind})`,
                                disabled: selectedPrincipal.disabled,
                            } : undefined}
                            loading={loadingPrincipals}
                            errorMessage={principalError}
                            disabled={busy}
                            onQueryChange={onPrincipalQueryChange}
                            onValueChange={(key) => {
                                if (key === null) return;
                                const principal = principalMap.get(key);
                                if (principal) setSelectedPrincipal(principal);
                            }}
                        />
                        <NativeSelect aria-label="새 공유 역할"
                            value={selectedGrantRoleId}
                            disabled={busy || knownRoles.length === 0}
                            onChange={(event) =>
                                setGrantRoleId(event.target.value)}>
                            <option value="" disabled>역할 선택</option>
                            {knownRoles.map((role) => (
                                <option key={role.id} value={role.id}>
                                    {role.label ?? role.id}
                                </option>
                            ))}
                        </NativeSelect>
                        <Button type="button"
                            disabled={busy || !selectedPrincipal ||
                                !selectedGrantRoleId || !knownRoles.some((role) =>
                                    role.id === selectedGrantRoleId,
                                ) || !!selectedPrincipal.disabled ||
                                selectedPrincipal.kind === "link"}
                            onClick={() => {
                                if (!selectedPrincipal ||
                                    !selectedGrantRoleId ||
                                    selectedPrincipal.kind === "link") return;
                                const principal = selectedPrincipal;
                                void runAction(
                                    `add:${principalKey(principal)}`,
                                    async () => {
                                        await onAddGrant(
                                            principal,
                                            selectedGrantRoleId,
                                        );
                                        setSelectedPrincipal(null);
                                    },
                                );
                            }}>
                            추가
                        </Button>
                    </div>
                )}
            </section>

            <section aria-labelledby={`${generatedId}-inherited-heading`}
                className="grid min-w-0 gap-3">
                <h3 id={`${generatedId}-inherited-heading`}
                    className="m-0 text-sm font-semibold">
                    상속된 권한
                </h3>
                {accessState === "available" && inheritedGrants.length > 0 ? (
                    <ul className="m-0 grid list-none gap-2 p-0">
                        {inheritedGrants.map((grant) =>
                            renderGrant(grant, "inherited"),
                        )}
                    </ul>
                ) : accessState === "available" ? (
                    <p className="m-0 text-sm text-muted">
                        상속된 권한이 없습니다.
                    </p>
                ) : (
                    <p className="m-0 text-sm text-muted">
                        상속 권한 결과를 확인할 수 없습니다.
                    </p>
                )}
            </section>

            <section aria-labelledby={`${generatedId}-effective-heading`}
                className="grid min-w-0 gap-3">
                <h3 id={`${generatedId}-effective-heading`}
                    className="m-0 text-sm font-semibold">
                    실효 권한
                </h3>
                {accessState !== "available" ? (
                    <p className="m-0 text-sm text-muted">
                        실효 권한 결과를 확인할 수 없습니다.
                    </p>
                ) : effectivePermissions.length === 0 ? (
                    <p className="m-0 text-sm text-muted">
                        표시할 실효 권한 결과가 없습니다.
                    </p>
                ) : (
                    <ul className="m-0 grid list-none gap-2 p-0">
                        {effectivePermissions.map((permission, index) => {
                            const resultText = permissionStateLabel(
                                permission.result,
                            );
                            const id = `${permission.principal.kind}:` +
                                `${permission.principal.id}:${index}`;
                            return (
                                <li key={id} className={
                                    "grid min-w-0 gap-1 rounded-sm border " +
                                    "border-border bg-surface p-[var(--space-3)] " +
                                    "@md:grid-cols-[minmax(0,1fr)_auto]"
                                }>
                                    <span className="min-w-0 break-words text-sm">
                                        {permission.principal.name}
                                        <span className="ml-2 text-xs text-muted">
                                            {permission.principal.kind}
                                        </span>
                                    </span>
                                    {permission.result.state === "known" ? (
                                        <span className="text-sm">
                                            {displayRole(
                                                permission.result.role,
                                                roles,
                                            )}
                                        </span>
                                    ) : (
                                        <span role={
                                            permission.result.state ===
                                                "inaccessible"
                                                ? "alert" : "status"
                                        } className={cn(
                                            "text-sm",
                                            permission.result.state ===
                                                "inaccessible"
                                                ? "text-danger" : "text-muted",
                                        )}>
                                            {resultText}
                                        </span>
                                    )}
                                </li>
                            );
                        })}
                    </ul>
                )}
            </section>

            <section aria-labelledby={`${generatedId}-link-heading`}
                className={
                    "grid min-w-0 gap-3 rounded-sm border border-border " +
                    "bg-surface p-[var(--space-3)]"
                }>
                <h3 id={`${generatedId}-link-heading`}
                    className="m-0 text-sm font-semibold">
                    링크 접근
                </h3>
                {linkAccess.state === "known" ? (
                    <div className="grid min-w-0 gap-3 @md:grid-cols-2">
                        <label className="flex min-w-0 items-center gap-3 text-sm">
                            <Switch
                                checked={linkAccess.enabled}
                                disabled={!mayEdit || busy ||
                                    !onLinkAccessChange}
                                aria-label="링크 접근 사용"
                                onCheckedChange={(enabled) => {
                                    if (onLinkAccessChange) {
                                        void runAction("link", () =>
                                            onLinkAccessChange({
                                                enabled,
                                                roleId: linkAccess.role.id,
                                            }),
                                        );
                                    }
                                }}
                            />
                            {linkAccess.enabled
                                ? "링크 접근 사용" : "링크 접근 사용 안 함"}
                        </label>
                        <NativeSelect aria-label="링크 접근 역할"
                            value={linkAccess.role.id}
                            disabled={!mayEdit || busy ||
                                !onLinkAccessChange || !linkAccess.enabled}
                            onChange={(event) => {
                                if (onLinkAccessChange) {
                                    void runAction("link", () =>
                                        onLinkAccessChange({
                                            enabled: linkAccess.enabled,
                                            roleId: event.target.value,
                                        }),
                                    );
                                }
                            }}>
                            {roleSelectOptions(linkAccess.role, roles).map(
                                (role) => (
                                    <option key={role.id} value={role.id}
                                        disabled={role.state !== "known"}>
                                        {role.state === "known"
                                            ? role.label ?? role.id
                                            : displayRole(role, roles)}
                                    </option>
                                ),
                            )}
                        </NativeSelect>
                    </div>
                ) : (
                    <p role={linkAccess.state === "inaccessible"
                        ? "alert" : "status"}
                        className={cn(
                            "m-0 text-sm",
                            linkAccess.state === "inaccessible"
                                ? "text-danger" : "text-muted",
                        )}>
                        {linkAccess.message ?? (
                            linkAccess.state === "pending"
                                ? "링크 접근 권한을 확인하는 중입니다."
                                : linkAccess.state === "unknown"
                                    ? "링크 접근 권한을 확인할 수 없습니다."
                                    : "링크 접근 권한에 접근할 수 없습니다."
                        )}
                    </p>
                )}
            </section>
        </section>
    );
}

export { SharePermissionPanel };
export type {
    EffectivePermission,
    PermissionGrant,
    PermissionResolution,
    PermissionRole,
    ShareLinkAccess,
    SharePermissionPanelProps,
    SharePrincipal,
    SharePrincipalKind,
};
